@GetMapping("Statement_Do_While_001_T/{cmd}")
  public Map<String, Object> statement_do_while_001_t(@PathVariable String cmd) {
    Map<String, Object> modelMap = new HashMap<>();
    try {
      int i = 0;
      // 场景特点：污点变量在do-while循环体中使用
      do {
        Runtime.getRuntime().exec(cmd);
        i++;
      } while (i < 1);
      modelMap.put("status", "success");
    } catch (Exception e) {
      modelMap.put("status", "error");
    }
    return modelMap;
  }

